// ─── Alert ───────────────────────────────────────────────────────────────────

import { cn } from '@/lib/utils';
import { createButton } from './button';

/**
 * Toca `.nds-animate-out` e só então executa `done`. As classes vivem em
 * `utilities.css` e servem a qualquer componente que apareça/suma em runtime.
 *
 * O timeout NÃO é redundância defensiva genérica: sem ele o alert nunca sai da
 * tela quando a animação não chega a existir — `prefers-reduced-motion` a
 * suprime e `animationend` jamais dispara — nem quando o nó é escondido
 * (display/visibility, aba em background) antes de a animação completar. Quem
 * vencer a corrida remove o nó; `done` roda uma vez só.
 */
const EXIT_FALLBACK_MS = 300;  // --duration-base (200ms) + folga
const ENTER_FALLBACK_MS = 450; // --duration-spring (400ms) + folga

function runExitAnimation(el: HTMLElement, done: () => void): void {
  let finalizado = false;
  const finalizar = (event?: Event) => {
    // animationend borbulha: uma animação de qualquer descendente encerraria a
    // saída antes da hora. Só o próprio elemento conta.
    if (event && event.target !== el) return;
    /* v8 ignore next -- guarda de dupla finalização: os dois caminhos que
       chamam (animationend e timeout) removem listener e timer antes de sair,
       então não há ordem de eventos que a alcance. */
    if (finalizado) return;
    finalizado = true;
    window.clearTimeout(timer);
    el.removeEventListener('animationend', finalizar);
    done();
  };

  // Fechar antes da entrada terminar deixaria as duas classes no elemento.
  el.classList.remove('nds-animate-in');
  el.classList.add('nds-animate-out');
  el.addEventListener('animationend', finalizar);
  const timer = window.setTimeout(finalizar, EXIT_FALLBACK_MS);
}

export type AlertVariant = 'default' | 'destructive' | 'success' | 'warning' | 'info';

/**
 * Semântica de anúncio do elemento raiz.
 *
 * - `alert`  — live region ASSERTIVA: o leitor de tela interrompe o que estiver
 *   fazendo e anuncia na hora. Por WAI-ARIA só vale para mensagem urgente que
 *   **surge em tempo de execução**.
 * - `status` — live region polida: anuncia sem interromper.
 * - `note`   — NÃO é live region. É o certo para alert estático, já presente
 *   quando a página carrega.
 */
export type AlertRole = 'alert' | 'status' | 'note';

export interface AlertOptions {
  variant?: AlertVariant;
  /**
   * Semântica de anúncio no elemento raiz — default `'alert'`.
   * Use `'note'` para conteúdo estático (não vira live region).
   */
  role?: AlertRole;
  /** Additional CSS classes to append. */
  className?: string;
  /** Renderiza o botão de fechar (X) no canto superior direito. */
  dismissible?: boolean;
  /** Disparado uma única vez, quando o usuário aciona o botão de fechar. */
  onDismiss?: () => void;
  /** aria-label do botão de fechar. */
  dismissLabel?: string;
}

export interface AlertTitleOptions {
  text?: string;
  /** Nível do heading do título — default 'h5'. */
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';
  className?: string;
}

export interface AlertDescriptionOptions {
  text?: string;
  className?: string;
}

export function createAlert(options: AlertOptions = {}): HTMLElement {
  const { variant = 'default', role = 'alert', className, dismissible = false, onDismiss, dismissLabel = 'Fechar alerta' } = options;

  const el = document.createElement('div');
  el.dataset.slot = 'alert';
  // PATCH: a11y — `role` configurável. Fixo em 'alert' o componente era live
  // region assertiva mesmo estático, e o leitor de tela pulava para ele no
  // carregamento (ver PATCHES.md#alert-role).
  el.setAttribute('role', role);
  el.className = cn(variant === 'default' ? 'nds-alert' : `nds-alert nds-alert-${variant}`, className);

  // PATCH: api — variante dismissible: botão X remove o alert e chama onDismiss
  // uma única vez (ver PATCHES.md#alert-dismissible)
  if (dismissible) {
    // O snippet da story vem do outerHTML — a configuração precisa estar no DOM.
    el.dataset.dismissible = 'true';

    // Entrada: a classe é TRANSITÓRIA. Fica no DOM só enquanto a animação
    // roda e é removida em seguida — se ficasse, um ambiente que não avança
    // a animação (headless) manteria o alert preso em opacity: 0, invisível.
    el.classList.add('nds-animate-in');
    const limparEntrada = (event?: Event) => {
      if (event && event.target !== el) return; // animationend borbulha
      el.classList.remove('nds-animate-in');
      el.removeEventListener('animationend', limparEntrada);
    };
    el.addEventListener('animationend', limparEntrada);
    window.setTimeout(limparEntrada, ENTER_FALLBACK_MS);

    let dismissed = false;
    const dismissButton = createButton({
      variant: 'ghost',
      size: 'icon-sm',
      ariaLabel: dismissLabel,
      class: 'nds-alert-dismiss',
      onClick: () => {
        if (dismissed) return;
        dismissed = true;
        // Anima a saída antes de remover. NUNCA depender só de animationend:
        // com prefers-reduced-motion a animação não existe e o evento nunca
        // dispara; em ambiente que não compõe quadros (Chromium headless) ela
        // fica presa. O timeout é o que garante que o nó sempre sai.
        runExitAnimation(el, () => {
          el.remove();
          onDismiss?.();
        });
      },
    });
    dismissButton.dataset.slot = 'alert-dismiss';
    dismissButton.appendChild(createDismissIcon());
    el.appendChild(dismissButton);
    // Ordem no DOM: o consumidor appenda ícone/título/descrição DEPOIS do
    // createAlert, o que deixaria o X como primeiro filho — leitor de tela
    // anunciaria "Fechar alerta" antes do conteúdo, divergindo das outras 3
    // stacks (lá o X renderiza após os children). O microtask reposiciona o
    // botão para o fim depois que os appends síncronos do consumidor rodarem.
    // Visual não muda (position: absolute); só a ordem de leitura e de Tab.
    queueMicrotask(() => {
      /* v8 ignore next -- o caminho "já é o último" exige alert dismissible sem
         nenhum conteúdo: o botão só deixa de ser último porque o consumidor
         appenda depois, e alert vazio não é caso de uso. */
      if (el.lastElementChild !== dismissButton) el.appendChild(dismissButton);
    });
  }

  return el;
}

export function createAlertTitle(options: AlertTitleOptions = {}): HTMLElement {
  const { text = '', as = 'h5', className } = options;

  // PATCH: api — nível do heading configurável via `as`, default 'h5'
  // (ver PATCHES.md#alert-title-desc-semantics)
  const el = document.createElement(as);
  el.dataset.slot = 'alert-title';
  el.className = cn('nds-alert-title', className);
  /* v8 ignore next -- `text` tem default ''; o ramo falso é o título montado por
     appendChild, que nenhuma story exercita e a documentação não oferece. */
  if (text) el.textContent = text;

  return el;
}

export function createAlertDescription(options: AlertDescriptionOptions = {}): HTMLElement {
  const { text = '', className } = options;

  // <section> preserva a semântica de landmark da descrição. CSS aceita tanto
  // section quanto qualquer elemento com class nds-alert-description.
  const el = document.createElement('section');
  el.dataset.slot = 'alert-description';
  el.className = cn('nds-alert-description', className);
  /* v8 ignore next -- `text` tem default ''; o ramo falso é a descrição montada
     por appendChild, que nenhuma story exercita e a documentação não oferece. */
  if (text) el.textContent = text;

  return el;
}

export interface AlertActionOptions {
  className?: string;
}

/**
 * Slot de ação no canto superior direito do alert (`.nds-alert-action`).
 * Devolve o container vazio — o consumidor injeta o botão via `createButton`.
 * O CSS já reserva o padding-inline-end quando o alert tem `.nds-alert-action`.
 */
export function createAlertAction(options: AlertActionOptions = {}): HTMLElement {
  const { className } = options;

  const el = document.createElement('div');
  el.dataset.slot = 'alert-action';
  el.className = cn('nds-alert-action', className);

  return el;
}

// ─── Icons ────────────────────────────────────────────────────────────────────

import { Info, AlertCircle, CheckCircle2, TriangleAlert, X } from 'lucide';

export type AlertIconType = 'info' | 'error' | 'success' | 'warning';

type LucideIconNode = [string, Record<string, string>];

const ALERT_ICON_MAP: Record<AlertIconType, LucideIconNode[]> = {
  info:    Info as unknown as LucideIconNode[],
  error:   AlertCircle as unknown as LucideIconNode[],
  success: CheckCircle2 as unknown as LucideIconNode[],
  warning: TriangleAlert as unknown as LucideIconNode[],
};

export function createAlertIcon(type: AlertIconType): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  // .nds-alert > svg já define width/height 16px via CSS — não precisa setar via class.

  for (const [tag, attrs] of ALERT_ICON_MAP[type]) {
    const child = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs)) child.setAttribute(k, v);
    svg.appendChild(child);
  }
  return svg;
}

/** Ícone X do botão de fechar — mesmo padrão de montagem por nós do lucide. */
function createDismissIcon(): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('fill', 'none');
  svg.setAttribute('stroke', 'currentColor');
  svg.setAttribute('stroke-width', '2');
  svg.setAttribute('stroke-linecap', 'round');
  svg.setAttribute('stroke-linejoin', 'round');
  svg.setAttribute('aria-hidden', 'true');
  svg.setAttribute('class', 'nds-icon');

  for (const [tag, attrs] of X as unknown as LucideIconNode[]) {
    const child = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs)) child.setAttribute(k, v);
    svg.appendChild(child);
  }
  return svg;
}

/*
 * ─── nds-alert ───────────────────────────────────────────────────────────────
 * Componente standalone — zero dependência externa de CSS.
 *
 * Estrutura:
 *   <div class="nds-alert" role="alert">
 *     <svg>...</svg>             ← opcional, vai pra coluna 1
 *     <h5 class="nds-alert-title">Title</h5>
 *     <section class="nds-alert-description"><p>Descrição…</p></section>
 *   </div>
 *
 * Variantes:
 *   .nds-alert                  → default (bg-muted, fg-card-foreground)
 *   .nds-alert.nds-alert-destructive → vermelho (texto destructive)
 *
 * Tokens: --muted, --card-foreground, --foreground, --destructive,
 *         --border, --radius-alert, --spacing-*
 */

.nds-alert {
  --alert-bg: hsl(var(--muted));
  --alert-fg: hsl(var(--card-foreground));
  --alert-border: hsl(var(--border));
  /* Tom base do gradiente animado da borda — as 4 variações saem daí.
     É o mesmo em TODAS as variantes, de propósito: o gradiente é acabamento, e
     acompanhar a cor semântica fazia o destructive girar vermelho e o success
     verde, competindo com o significado que o ícone e o título já carregam.
     Neutro, ele decora sem disputar leitura. */
  --alert-glow: hsl(var(--border));

  position: relative;
  display: grid;
  grid-template-columns: 0 1fr;
  align-items: flex-start;
  row-gap: var(--spacing-0-5);                  /* 2px */
  column-gap: 0;

  width: 100%;
  border: 1px solid var(--alert-border);
  border-radius: var(--radius-alert);
  padding-inline: var(--spacing-4);             /* 16px */
  padding-block: var(--spacing-2);              /* 8px */

  background-color: var(--alert-bg);
  color: var(--alert-fg);
  font-size: var(--text-control);                          /* 14px — text-sm */
  line-height: 1.5;
}

/* Quando há ícone svg como filho, abre coluna pro ícone */
.nds-alert:has(> svg) {
  grid-template-columns: var(--spacing-4) 1fr;
  column-gap: var(--spacing-2);                 /* 8px */
}

.nds-alert > svg {
  width: var(--spacing-4);                      /* 16px */
  height: var(--spacing-4);
  color: currentColor;
  translate: 0 var(--spacing-0-5);              /* alinha visualmente com 1ª linha do título */
}

/* Título — h1-h6 ou strong ou [data-title] */
.nds-alert-title,
.nds-alert > h1,
.nds-alert > h2,
.nds-alert > h3,
.nds-alert > h4,
.nds-alert > h5,
.nds-alert > h6,
.nds-alert > strong,
.nds-alert > [data-title] {
  grid-column-start: 2;
  min-height: var(--spacing-4);
  margin: 0;
  font-size: inherit;
  font-weight: var(--font-weight-semi-bold, 600);
  letter-spacing: -0.01em;
  line-height: 1.4;
}

/* Descrição — section nativa (semântica de landmark preservada).
 * Display grid para empilhar parágrafos com gap consistente.
 * Texto corrido sempre em foreground — a regra dos containers já valia para as
 * variantes semânticas; o default alinhou quando o fundo virou --muted. */
.nds-alert-description,
.nds-alert > section {
  grid-column-start: 2;
  display: grid;
  gap: var(--spacing-1);                        /* 4px entre <p> */
  justify-items: start;
  font-size: inherit;
  color: hsl(var(--foreground));
}
.nds-alert-description > p,
.nds-alert > section > p {
  margin: 0;
  line-height: 1.625;
}
.nds-alert-description ul,
.nds-alert > section ul {
  list-style: disc inside;
  font-size: inherit;
  margin: 0;
  padding: 0;
}

/* ── Variantes semânticas ──────────────────────────────────────────────────── *
 * Regra WCAG 2.2 AA (contraste 4.5:1):
 *   - Container colorido: bg-soft + border-soft com tons da cor semântica
 *   - Ícone e título: podem usar a cor semântica (são curtos, contraste 3:1 ok)
 *   - Texto corrido (description): SEMPRE --foreground para garantir 4.5:1
 * ────────────────────────────────────────────────────────────────────────── */

/* destructive — vermelho com bg soft */
.nds-alert-destructive {
  --alert-bg: hsl(var(--destructive) / 0.1);
  --alert-fg: hsl(var(--destructive));
  --alert-border: hsl(var(--destructive) / 0.3);
}

/* success — verde com bg soft */
.nds-alert-success {
  --alert-bg: hsl(var(--success) / 0.1);
  --alert-fg: hsl(var(--success));
  --alert-border: hsl(var(--success) / 0.3);
}

/* warning — âmbar com bg soft */
.nds-alert-warning {
  --alert-bg: hsl(var(--warning) / 0.1);
  --alert-fg: hsl(var(--warning));
  --alert-border: hsl(var(--warning) / 0.3);
}
/* Em warning, a cor âmbar não atinge 4.5:1 sobre bg-soft.
   Título usa --foreground; o ícone (curto, 3:1) mantém --alert-fg. */
.nds-alert-warning .nds-alert-title,
.nds-alert-warning > h1,
.nds-alert-warning > h2,
.nds-alert-warning > h3,
.nds-alert-warning > h4,
.nds-alert-warning > h5,
.nds-alert-warning > h6 {
  color: hsl(var(--foreground));
}

/* info — azul com bg soft */
.nds-alert-info {
  --alert-bg: hsl(var(--info) / 0.1);
  --alert-fg: hsl(var(--info));
  --alert-border: hsl(var(--info) / 0.3);
}
/* O azul do info passa nos dois temas depois que --info subiu de 53% para 64%
 * no escuro: 6.16:1 no claro e 4.64:1 no escuro, sobre o próprio bg soft. Havia
 * aqui um override que forçava --foreground no escuro; ele existia porque o
 * token estava escuro demais, e o lugar do conserto era o tema, não a variante.
 * O título é 14px semibold, que NÃO é texto grande pela WCAG (precisaria de
 * 18.66px em negrito), então o limite dele é 4.5 e não 3. */

/* ── Action (botão no canto superior direito) ─────────────────────────────── */
.nds-alert-action {
  position: absolute;
  top: var(--spacing-2);
  right: var(--spacing-2);
}

.nds-alert:has(.nds-alert-action) {
  padding-inline-end: var(--spacing-18);
}

/* ── Dismiss (X no canto superior direito) ────────────────────────────────── *
 * Variante dismissible: o próprio Alert renderiza o botão de fechar (Button
 * ghost icon-sm da stack). Mutuamente exclusivo com .nds-alert-action por
 * design — quem precisa de ação usa a composição AlertAction. */
.nds-alert-dismiss {
  position: absolute;
  top: var(--spacing-1);
  right: var(--spacing-1);
  color: hsl(var(--muted-foreground));
}

.nds-alert-dismiss:hover {
  color: hsl(var(--foreground));
}

.nds-alert:has(.nds-alert-dismiss) {
  padding-inline-end: var(--spacing-10);        /* 40px — botão icon-sm + respiro */
}

/* Links dentro de título/descrição */
.nds-alert-title a,
.nds-alert-description a {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.nds-alert-title a:hover,
.nds-alert-description a:hover {
  color: hsl(var(--foreground));
}

/* A regra "descrição sempre foreground" vale para TODAS as variantes e vive na
   regra base da descrição — o bloco por-variante que existia aqui forçava o
   mesmo valor e saiu como redundância. */

/* ── Gradiente animado na borda ───────────────────────────────────────────────
 * Um gradiente de 4 tons neutros (dois mais claros, dois mais escuros, todos
 * derivados da cor de borda do tema) gira ao redor do alert, dá duas voltas e
 * desacelera até parar. É o MESMO gradiente em todas as variantes.
 *
 * Não entra na anatomia: um ::after absoluto, fora do fluxo do grid e sem
 * ponteiro. Nenhum elemento novo no DOM, nenhuma classe nova para as stacks.
 *
 * O que gira é a PINTURA, não um elemento — é a técnica da referência (Ana
 * Tudor, pen qEdRXjV): `conic-gradient` num anel mascarado, com o ângulo inicial
 * animado por propriedade registrada. Como nada se desloca, o anel acompanha a
 * curva das quinas por construção; as versões anteriores moviam um elemento pelo
 * caminho da borda e ele saía reto nas curvas.
 *
 * A referência usa `in hsl longer hue` para varrer o círculo de matiz inteiro
 * (arco-íris). Aqui os 4 tons saem todos de `--alert-glow`, deslocando só a
 * lightness: o gradiente é monocromático e igual nas 5 variantes.
 */

/* O ângulo precisa ser propriedade REGISTRADA: custom property comum é string
   para o motor de animação e não interpola — o gradiente ficaria parado. */
@property --nds-alert-gradient-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@keyframes nds-alert-gradient-giro {
  from { --nds-alert-gradient-angle: 0deg; animation-timing-function: linear; }
  /* Velocidade constante até 1,5 volta; daí em diante a freada.
     A curva começa com inclinação 1,69 (= 0.54/0.32), que é a razão entre a
     velocidade do trecho linear (540deg/64%) e a média deste (180deg/36%) — é o
     que faz a junção não ter degrau. Termina em inclinação 0, que é a parada.
     A freada precisa desse tanto de pista: cabendo só nos últimos 15% do tempo,
     nenhuma curva cobre o que sobra sem primeiro ACELERAR. */
  64%  { --nds-alert-gradient-angle: 540deg; animation-timing-function: cubic-bezier(0.32, 0.54, 0.5, 1); }
  to   { --nds-alert-gradient-angle: 720deg; }
}

/* Separado do giro porque cada um tem seu perfil de tempo: o gradiente acende e
   apaga em rampa (surgir e sumir em opacidade cheia entrega o corte) enquanto o
   giro segue linear. Ao apagar, a borda volta ao estado normal. */
@keyframes nds-alert-gradient-brilho {
  from { opacity: 0; }
  3%   { opacity: 1; }
  86%  { opacity: 1; }
  to   { opacity: 0; }
}

.nds-alert::after {
  content: "";
  position: absolute;
  inset: 0;                                     /* mesma caixa da borda */
  border-radius: inherit;
  /* 2px cobrem a borda de 1px e avançam 1px para dentro, sobre o padding — o
     anel fica mais visível sem que a caixa mude de tamanho nem o texto ande. */
  padding: 2px;

  /* 4 variações do tom da borda: duas mais claras, duas mais escuras. Os passos
     são deslocamentos de LIGHTNESS em oklch, não mistura com branco/preto —
     misturar comprime o lado claro quando a base já é clara: na variante default
     (borda cinza) `color-mix ... white 15%` e `40%` davam L 0,935 e 0,954, dois
     tons que ninguém distingue. Deslocando l, o passo é o mesmo em qualquer
     variante. `c` e `h` intactos: é sempre o mesmo tom.
     O 5º stop repete o 1º para o ciclo fechar sem emenda. */
  background: conic-gradient(
    from var(--nds-alert-gradient-angle),
    oklch(from var(--alert-glow) calc(min(l, 0.84) + 0.16) c h)   0%,
    oklch(from var(--alert-glow) calc(min(l, 0.84) + 0.08) c h)  25%,
    oklch(from var(--alert-glow) calc(max(l, 0.16) - 0.08) c h)  50%,
    oklch(from var(--alert-glow) calc(max(l, 0.16) - 0.16) c h)  75%,
    oklch(from var(--alert-glow) calc(min(l, 0.84) + 0.16) c h) 100%
  );
  /* Recorta o miolo: pinta padding-box MENOS content-box, sobrando só o anel.
     Sem isso o gradiente cobriria o alert inteiro. */
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask-composite: exclude;

  pointer-events: none;
  opacity: 0;                                   /* estado de repouso */
  /* 2 voltas em 7,2s — o trecho de cruzeiro sai a ~3,1s por volta.
     Duração derivada de token: sob prefers-reduced-motion as durações vão a 0ms
     e o efeito se anula sozinho; a regra abaixo é a garantia explícita.
     Delay de 3s é valor de produto — nenhuma duração da escala chega perto. */
  animation:
    nds-alert-gradient-giro    calc(var(--duration-stately) * 9) linear 3s forwards,
    nds-alert-gradient-brilho  calc(var(--duration-stately) * 9) linear 3s forwards;
}

@media (prefers-reduced-motion: reduce) {
  .nds-alert::after {
    animation: none;
  }
}
